  if (b.md && (b.md.length + ln.length) > 1400) { blocos.push(b); b = { ini: null, fim: null, md: '' }; }
  if (b.ini == null) b.ini = p.i; b.fim = p.i; b.md += (b.md ? '\n' : '') + ln;
